argv:
$ErrorActionPreference='Stop'
$dst='E:\boss-R65-CANARY-VERIFY-20261014-GPT6'
$sha='ff6b105fde40e3e292c883073f741b4970523ff2'
if(Test-Path -LiteralPath $dst){throw 'REFUSE_OVERWRITE_EXISTING_CHECKOUT'}
& git.exe clone --depth 1 --single-branch --no-tags --branch 'agent/qa-r65-autonomy-single-canary-20261014' 'https://github.com/foto6/boss.git' $dst 2>&1|Out-Null
if($LASTEXITCODE -ne 0){throw 'QA_CLONE_FAILED'}
$head=([string](& git.exe -C $dst rev-parse HEAD)).Trim()
if($head -ne $sha){throw ('QA_BRANCH_SHA_MOVED '+$head)}
$log=Join-Path $dst 'R65_NODE_CANARY_GPT6.txt'
Push-Location -LiteralPath $dst
try{
 & node.exe --test tests/r65_autonomy_canary.test.cjs 2>&1|Out-File -LiteralPath $log -Encoding UTF8
 $rc=$LASTEXITCODE
}finally{Pop-Location}
Write-Output ('QA_EXACT_SOURCE='+$head)
Write-Output ('NODE_TEST_EXIT='+$rc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 25|ForEach-Object{Write-Output $_.Line}
Write-Output ('QA_TEST_LOG='+$log)
Write-Output ('PRODUCTION_BRIDGE_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0){throw 'QA_OFFLINE_NODE_TEST_FAIL'}
